S = "Hakeem Force Academy"
QS = [
(S, "What is sec 2x equal to?", ["1 / sin 2x", "2 sec x", "1 / cos 2x", "1 / (2 cos x)"], 2, "Secant is the reciprocal of cosine, so sec of any angle is 1 divided by cos of that angle. For the angle 2x this gives sec 2x = 1 / cos 2x.", "Sec 2x is not the same as 2 sec x.", [2944]),
(S, "What is the gap in years between the first (1956) and second (1962) constitution of Pakistan?", ["4 years", "6 years", "3 years", "9 years"], 1, "The first constitution came into force in March 1956 and the second in June 1962. 1962 minus 1956 is 6 years.", "The 1973 Constitution is the third and current constitution of Pakistan.", [1109]),
(S, "In what year did Quaid-e-Azam end his self-imposed exile in London and return to India to lead the Muslim League?", ["1926", "1930", "1934", "1937"], 2, "Jinnah stayed in London from about 1930 and returned to India in 1934 at the request of Liaquat Ali Khan and others. He then took up the leadership of the Muslim League.", "Sources differ slightly on when he left, but 1934 is the standard year of return.", [2476, 1186, 3603]),
(S, "In which year did Quaid-e-Azam go into self-imposed exile in London?", ["1930", "1920", "1940", "1925"], 0, "After the Round Table Conferences, Jinnah was disappointed with Indian politics and settled in London around 1930. He returned in 1934.", "Some sources say 1931; most Pakistani textbooks give 1930.", [469]),
(S, "Fill in the preposition: A private secretary has no authority ___ his boss.", ["on", "over", "at", "with"], 1, "The correct phrase is authority over someone, meaning power to control them.", "We say authority over a person but authority on a subject.", [1713]),
(S, "Under the 1956 Constitution of Pakistan, who appointed the Prime Minister?", ["The Chief Justice", "The President", "The Governor General", "The Senate"], 1, "The 1956 Constitution gave a parliamentary system. The President appointed as Prime Minister the member of the National Assembly who commanded the confidence of the majority.", "The 1956 Constitution had a one-house National Assembly and no Senate.", [2044]),
(S, "What is the total number of women seats in the Senate of Pakistan?", ["16", "17", "14", "23"], 1, "Each of the four provinces has 4 seats for women, which is 16, and Islamabad has 1 women seat. The total is 17.", "The Senate has 96 members in all.", [1885]),
(S, "Which letter is used to denote the set of rational numbers?", ["R", "N", "Z", "Q"], 3, "Rational numbers are written as quotients (fractions) of integers, so the set is denoted by Q.", "N is natural numbers, Z is integers and R is real numbers.", [1286]),
(S, "In a class of 33 students, 7 are boys. What is the percentage of girls (approximately)?", ["21.21%", "78.79%", "82%", "70%"], 1, "Girls = 33 - 7 = 26. Percentage = 26 / 33 x 100 = 78.79%.", "Boys are 7 / 33 x 100 = 21.21%, and the two add to 100%.", [2058]),
(S, "In a class of 33 students, the boys outnumber the girls by 7. How many girls are there?", ["13", "20", "16", "10"], 0, "Let girls = g, then boys = g + 7. So g + g + 7 = 33, 2g = 26 and g = 13.", "There are 20 boys in this class.", [401, 2059]),
(S, "What is the range of Pakistan's Shaheen-III missile?", ["750 km", "1500 km", "900 km", "2750 km"], 3, "Shaheen-III is a surface-to-surface ballistic missile with a range of about 2750 km.", "Shaheen-I has a range of about 750 km.", [3330]),
(S, "In which city is Shalimar Bagh (Shalimar Gardens) located?", ["Delhi", "Multan", "Lahore", "Peshawar"], 2, "The Shalimar Gardens are in Lahore, Pakistan. They were built by Mughal emperor Shah Jahan around 1641.", "The Shalimar Gardens and Lahore Fort are a UNESCO World Heritage Site.", [3760, 1212]),
(S, "With which country does Pakistan share its longest border?", ["Afghanistan", "India", "China", "Iran"], 1, "The Pakistan-India border, including the Line of Control, is over 3000 km long. This is longer than the Afghan border of about 2600 km.", "Pakistan's border with China is about 590 km.", [1401]),
(S, "Which province (autonomous region) of China shares a border with Pakistan?", ["Tibet", "Xinjiang", "Yunnan", "Sichuan"], 1, "Xinjiang in the far west of China borders Gilgit-Baltistan of Pakistan at the Khunjerab Pass.", "The Karakoram Highway links Pakistan to Xinjiang.", [4272]),
(S, "Which letter comes next in the series: b5, g8, l11, q14, ?", ["u17", "v17", "v16", "w17"], 1, "Letters move 5 steps each time (b, g, l, q, v) and the numbers go up by 3 (5, 8, 11, 14, 17). So the next term is v17.", "Skipping 4 letters between terms gives a step of 5.", [2575]),
(S, "Find the next letter in the series: A C G M ?", ["S", "T", "R", "U"], 3, "Positions are 1, 3, 7, 13. The gaps are 2, 4, 6, so the next gap is 8, giving position 21, which is U.", "The gaps in this series are even numbers rising by 2.", [2963]),
(S, "What comes next in the series: Z3, Y6, X9, ?", ["W12", "V12", "W15", "W11"], 0, "Letters go backward by one (Z, Y, X, W) and numbers go up by 3 (3, 6, 9, 12). So the next term is W12.", "Z is the 26th letter and goes down one position each time.", [3464]),
]
